<template><section class="resource-browser" data-testid="resource-browser"><header><b>RESOURCES</b><span>{{store.scene.resources.length}}</span></header><div class="resource-scroll" tabindex="0" role="list" aria-label="模型资源列表"><div v-if="!store.scene.resources.length" class="empty-panel">当前模型没有已解析资源</div><div v-for="(resource,index) in store.scene.resources" :key="resource" class="resource-item" role="listitem"><span>{{index+1}}</span><code :title="resource">{{resourceName(resource)}}</code></div></div></section></template>
<script setup lang="ts">import {useEditorStore} from '@/stores/editor';const store=useEditorStore();function resourceName(value:string){const name=new URL(value,location.origin).searchParams.get('name');return name||value.split('/').pop()||value}</script>
<style scoped>.resource-browser{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;overflow:hidden}.resource-browser header{flex:0 0 auto;display:flex;justify-content:space-between;padding:12px 14px;border-bottom:1px solid #253542;color:#7590a4;font-size:11px}.resource-scroll{flex:1 1 auto;min-height:0;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;scrollbar-gutter:stable;padding:6px}.resource-scroll:focus-visible{outline:1px solid #31a8ed;outline-offset:-1px}.resource-item{display:grid;grid-template-columns:24px minmax(0,1fr);gap:5px;padding:7px;border-bottom:1px solid #1d2b37}.resource-item span{color:#4b718b}.resource-item code{overflow:hidden;text-overflow:ellipsis;color:#a9bfce}</style>
